const menu=document.querySelector('.menu');
const nav=document.querySelector('nav');
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Tutup menu':'Buka menu');nav.classList.toggle('open',open);menu.textContent=open?'✕':'☰'});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Buka menu');menu.textContent='☰'}));
const screens={launcher:{src:'assets/launcher.jpeg',title:'Semua dimulai dari sini.',caption:'Launcher: pilihan preset dan akses game',copy:'Pilih preset grafis dan akses game dari halaman utama launcher. Angka FPS pada gambar adalah label preset, bukan jaminan performa.'},mods:{src:'assets/mods.png',title:'Sesuaikan pengalaman bermain.',caption:'Mods: kategori dan pratinjau mod',copy:'Jelajahi kategori kendaraan, senjata, visual, dan gameplay. Screenshot menampilkan pratinjau, bukan unduhan mod dari website ini.'},data:{src:'assets/data.png',title:'Ketahui apa yang tersimpan.',caption:'Data: informasi game, perangkat, dan save',copy:'Layar Data merangkum berkas game, perangkat, penyimpanan, dan save. Informasi pada gambar berasal dari perangkat pengguna, bukan hasil deteksi browser Anda.'},settings:{src:'assets/settings.png',title:'Kendali ada di tangan Anda.',caption:'Settings: resolusi, tampilan, dan rasio layar',copy:'Atur resolusi, mode layar, dan aspek rasio melalui aplikasi. Pengaturan pada gambar hanya contoh dan tidak diterapkan ke perangkat Anda.'}};
const tabs=[...document.querySelectorAll('[role=tab]')];
function selectTab(tab){tabs.forEach(t=>{const selected=t===tab;t.setAttribute('aria-selected',String(selected));t.tabIndex=selected?0:-1});const data=screens[tab.dataset.tab];const img=document.querySelector('#gallery-img');img.src=data.src;img.alt=data.caption;document.querySelector('#gallery-title').textContent=data.title;document.querySelector('#gallery-copy').textContent=data.copy;const button=document.querySelector('.gallery-image');button.dataset.image=data.src;button.dataset.caption=data.caption;document.querySelector('#gallery-panel').setAttribute('aria-labelledby',tab.id)}
tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>selectTab(tab));tab.addEventListener('keydown',event=>{let next;if(event.key==='ArrowRight')next=(index+1)%tabs.length;if(event.key==='ArrowLeft')next=(index-1+tabs.length)%tabs.length;if(event.key==='Home')next=0;if(event.key==='End')next=tabs.length-1;if(next!==undefined){event.preventDefault();selectTab(tabs[next]);tabs[next].focus()}})});
const dialog=document.querySelector('#lightbox');
document.querySelectorAll('[data-image]').forEach(button=>button.addEventListener('click',()=>{const img=document.querySelector('#lightbox-img');img.src=button.dataset.image;img.alt=button.dataset.caption;document.querySelector('#lightbox-caption').textContent=button.dataset.caption;dialog.showModal()}));
document.querySelector('#close-lightbox').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()}});
const checks=[...document.querySelectorAll('.check-box input')];
checks.forEach(input=>input.addEventListener('change',()=>{const count=checks.filter(c=>c.checked).length;document.querySelector('#check-status').textContent=count===3?'3 dari 3 selesai. Lanjutkan dengan panduan proyek.':`${count} dari 3 persiapan selesai`}));
